# owner: platform
"""Lay students out in rows for a seating chart."""

from typing import List

from rosterkit.models import Student


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _chunks(items: list, size: int) -> List[list]:
    return [items[i:i + size] for i in range(0, len(items), size)]


def _format_row(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"


# ---
def seat_rows(students, per_row):
    """One text line per row, students sorted by last name."""
    if per_row < 1 or not students:
        raise ValueError("need students and a positive row size")
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, per_row)
    return [_format_row(n, r) for n, r in enumerate(rows, 1)]
