# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_fills_rows(self):
        people = [make("Halloway", "Juno"), make("Dunmere", "Piet"), make("Adler", "Sam")]
        self.assertEqual(
            seat_rows(people, 2),
            ["Row 1: Adler, Sam | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_ties_break_on_first_name(self):
        people = [make("Lee", "Zed"), make("Lee", "Amy")]
        self.assertEqual(seat_rows(people, 5), ["Row 1: Lee, Amy | Lee, Zed"])

    def test_bad_seat_counts_raise(self):
        for bad in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows([make("A", "B")], bad)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
EOF
